contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 d, uint256 a) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(address(this).balance >= d);
        require(d > 0);
        require(a <= address(this).balance + d);
        c.deposit{value: d}(); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;
        bool expectedRevert = (a > d);
        bool reverted;
        c.withdraw(a); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(
            (a <= d && !reverted && address(this).balance == selfBalBefore + a && address(c).balance == cBalBefore - a)
            ||
            (a > d && reverted && address(this).balance == selfBalBefore && address(c).balance == cBalBefore)
        );
    }

    receive() external payable {}
}

