// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 d, uint256 a) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= d);
        vm.assume(d > 0);
        vm.assume(a <= address(this).balance + d);
        try c.deposit{value: d}() {} catch { return; }
        uint256 cBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;
        bool expectedRevert = (a > d);
        bool reverted;
        try c.withdraw(a) { reverted = false; } catch { reverted = true; }
        assertTrue((a <= d && !reverted && address(this).balance == selfBalBefore + a && address(c).balance == cBalBefore - a)
            ||
            (a > d && reverted && address(this).balance == selfBalBefore && address(c).balance == cBalBefore));
    }

    function testFuzz_run(uint256 d, uint256 a) public {
        _run(d, a);
    }

    receive() external payable {}
}
